/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
}

export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Derives a project key that collides with nothing in `taken`, the same way
 * `uniqueSlug` does for addresses: by appending 2, 3, …, trimming the base so
 * the result never exceeds four characters.
 */
export function uniqueProjectKey(base: string, taken: Iterable<string>): string {
  const used = new Set(taken);
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const suffixText = String(suffix);
    const candidate = `${base.slice(0, PROJECT_KEY_MAX_LENGTH - suffixText.length)}${suffixText}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}

