/**
 * A project may only be marked completed once none of its issues is open;
 * pausing and reactivating are unconditional, and a no-op status (completing
 * an already-completed project) skips the check entirely.
 */
export async function updateProject(
  actor: Actor,
  input: UpdateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.status === "completed" && project.status !== "completed") {
    const stats = await projectRepo.getProjectStats(input.orgId, project.id);
    if (stats.openIssues > 0) {
      throw new Error(
        `Project ${project.id} still has ${stats.openIssues} open issue(s)`,
      );
    }
  }

  return projectRepo.updateProject(input);
}

